// NewCreatePayload builds a mcp_management service create endpoint payload.
func NewCreatePayload(body *CreateRequestBody, cookie string) *mcpmanagement.CreatePayload {
	v := &mcpmanagement.CreatePayload{
		Password:     *body.Password,
		Name:         *body.Name,
		DepartmentID: *body.DepartmentID,
	}
	if body.Days != nil {
		v.Days = *body.Days
	}
	if body.Days == nil {
		v.Days = 30
	}
	v.Tools = make([]string, len(body.Tools))
	for i, val := range body.Tools {
		v.Tools[i] = val
	}
	v.Cookie = cookie

	return v
}

